export async function createTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  const parsed = z
    .object({
      subject: z.string().min(3).max(150),
      body: z.string().min(5).max(10000),
      priority: z.enum(["LOW", "NORMAL", "HIGH", "URGENT"]).default("NORMAL"),
    })
    .safeParse({
      subject: formData.get("subject"),
      body: formData.get("body"),
      priority: formData.get("priority") ?? "NORMAL",
    });
  if (!parsed.success) return { error: "Subject (3+) and message (5+) required." };

  const ticket = await db.ticket.create({
    data: {
      subject: parsed.data.subject,
      priority: parsed.data.priority,
      userId: user.id,
      messages: { create: { body: parsed.data.body, authorId: user.id, isStaff: false } },
    },
  });
  const admins = await db.user.findMany({ where: { role: "ADMIN" } });
  await db.notification.createMany({
    data: admins.map((a) => ({
      userId: a.id,
      title: `New ticket: ${parsed.data.subject}`,
      href: `/admin/support/${ticket.id}`,
    })),
  });
  redirect(`/dashboard/support/${ticket.id}`);
}

export async function replyTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireTicketActor();
  const ticketId = String(formData.get("ticketId") ?? "");
  const body = String(formData.get("body") ?? "").trim();
  if (body.length < 2 || body.length > 10000) return { error: "Message too short." };

  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
  if (!ticket) return { error: "Ticket not found." };
  const isStaff = user.isSupportStaff && ticket.userId !== user.id;
  if (ticket.userId !== user.id && !user.isSupportStaff) return { error: "Forbidden." };

  await db.$transaction([
    db.ticketMessage.create({ data: { ticketId, body, authorId: user.id, isStaff } }),
    db.ticket.update({
      where: { id: ticketId },
      data: { status: isStaff ? "ANSWERED" : "CUSTOMER_REPLY" },
    }),
  ]);

  if (isStaff) {
    await db.notification.create({
      data: {
        userId: ticket.userId,
        title: `Support replied: ${ticket.subject}`,
        href: `/dashboard/support/${ticketId}`,
      },
    });
  } else {
    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
    await db.notification.createMany({
      data: admins.map((a) => ({
        userId: a.id,
        title: `Ticket reply: ${ticket.subject}`,
        href: `/admin/support/${ticketId}`,
      })),
    });
  }
  revalidatePath(`/dashboard/support/${ticketId}`);
  revalidatePath(`/admin/support/${ticketId}`);
  return {};
}

/**
 * A TypeScript parameter type is a compile-time comment on a network endpoint.
 *
 * Every export of this file is POST-able with any JSON the caller likes, so the
 * `"OPEN" | "CLOSED"` annotations below constrained the components and nothing
 * else. `TicketStatus` also contains ANSWERED and CUSTOMER_REPLY — both writable
 * here — so a customer could stamp their own ticket ANSWERED and drop it out of
 * the support queue's "needs a reply" view without anyone having replied. Values
 * outside the enum reached Prisma and threw, which surfaces as a server error
 * page rather than a message. Both are fixed by validating at the boundary.
 */
