export async function terminateNxcloud(instanceId: string): Promise<NxCloudResult> {
  const user = await requireUser();
  await assertNotImpersonating();
  const inst = await db.nxCloudInstance.findUnique({ where: { id: instanceId }, select: { userId: true, serverId: true } });
  if (!inst) return { error: "Not found." };
  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (inst.serverId) {
    await db.job.create({ data: { type: "DELETE", serverId: inst.serverId } });
  }
  // Drop the wrapper row (tasks cascade). The DELETE job tears the VM down.
  await db.nxCloudInstance.delete({ where: { id: instanceId } });
  await db.auditLog.create({ data: { userId: user.id, action: "nxcloud.terminate", detail: instanceId } }).catch(() => {});
  revalidatePath("/dashboard/nxcloud");
  return { ok: true };
}

